actions.new_string:
def expand_paths(fs: "FileSystem", paths: Iterable[str]) -> Iterator[str]:
    for path in paths:
        try:
            if fs.isdir(path):
                yield from fs.find(path)
            else:
                yield path
        except Exception:  # noqa: BLE001
            # If the path doesn't exist or there's any other error,
            # just yield the path as is
            yield path
